const r={ui:{fig:"Fig. 1",title:"Neceser · anatomía",svgLabel:"Dibujo isométrico del neceser con cremallera, forro y esquinas redondas, y de cómo se cose, paso a paso.",prev:"Paso anterior",dot:(e,a)=>e?`Paso ${e}: ${a}`:a,start:"Pasos →",next:"Siguiente →",overview:"Vista general",stepOf:(e,a)=>`Paso ${e} de ${a}`,machine:e=>`Máquina: ${e.toLowerCase()}`,inThisStep:"En este paso",takeApart:"Desarmar",putTogether:"Armar",replay:"↻ Repetir",parts:"Piezas",allSteps:"Instrucciones paso a paso",endView:"CORTE",cutTitle:"Neceser · medidas de corte",cutAlt:"Esquema de corte de un neceser con cremallera y forro: exterior y forro de 23 × 31 cm cada uno, entretela termoadhesiva fina de 21 × 29 cm, cuatro piezas rosas de 18 × 10 cm, un cuadrado de entretela de 16 × 16 cm para las esquinas redondas y una cremallera de 20 cm.",cutCaption:"Las piezas que hay que cortar, con sus medidas, como en el paso 1."},stitches:{straight:"Puntada recta"},labels:{cm23:"23 cm",cm31:"31 cm",cm29:"29 cm",cm21:"21 cm",cm18:"18 cm",cm10:"10 cm",cm16:"16 cm",cm20:"20 cm",cm1:"1 cm",cm35:"3,5 cm",cm25:"2,5 cm",outerCotton:"exterior · algodón",liningCotton:"forro · mismo tamaño",ifaceThin:"entretela fina",pink4:"4 × rosa",ifaceCorners:"para las esquinas",zipper:"cremallera",radius8:"radio 8 cm",paperTemplate:"plantilla de papel",cutInHalf:"cortar por la mitad",twoHalves:"dos semicírculos",ironOn:"planchar",rightSides:"derecho con derecho",alongEdge:"coser por el borde",makeTwo:"haz dos",trimNotch:"recortar, hacer piquetes",turnOut:"dar la vuelta",wrongSideUp:"exterior, revés arriba",edges1:"1 cm de los bordes",middleBottom:"centro = base",rightSideUp:"derecho arriba",onBottomLine:"en la línea de la base",stitchRound:"coser alrededor",straight05:"lado recto: 0,5 cm",outerUp:"exterior, derecho arriba",zipperDown:"cremallera boca abajo",liningDown:"forro boca abajo",seam05:"costura 0,5 cm",liningAway:"abrir el forro",foldBoth:"doblar los dos",otherSide:"el otro lado",openZipper:"abrir la cremallera",opening6:"abertura 6 cm",outerHalf:"exterior",liningHalf:"forro",cutCorners:"recortar las esquinas",pinchSew:"abrir, coser de lado a lado",seamOnFold:"costura sobre el doblez",allFour:"las cuatro esquinas",turnThrough:"vuelta por la abertura",byHand:"cerrar a mano",pushLining:"meter el forro",closeZip:"cerrar la cremallera"},steps:[{title:"El neceser terminado",text:"Un neceser con cremallera y forro para maquillaje, lápices, tubos y cremas: algodón estampado con entretela fina y una esquina redonda rosa en cada extremo de la base. Toca el neceser para desarmarlo."},{title:"Corta las piezas",text:"Exterior y forro: 23 × 31 cm cada uno. Entretela termoadhesiva fina: 21 × 29 cm y un cuadrado de 16 × 16 cm. Cuatro piezas rosas de 18 × 10 cm. Una cremallera de 20 cm.",details:["Del algodón estampado corta el exterior, 23 × 31 cm. Corta el forro del mismo tamaño, 23 × 31 cm.","De la entretela termoadhesiva fina corta una pieza de 21 × 29 cm para el exterior y un cuadrado de 16 × 16 cm para las esquinas redondas.","Del algodón rosa corta cuatro piezas de 18 × 10 cm: dos para cada esquina.","También necesitas una cremallera de 20 cm.","Todos los márgenes de costura de este neceser son de 0,5 cm."]},{title:"La plantilla de las esquinas",text:"Dibuja en papel un círculo de 8 cm de radio y recórtalo. Cálcalo sobre el cuadrado de entretela de 16 cm, recorta el círculo y córtalo por la mitad.",details:["Haz una plantilla de papel: un círculo de 8 cm de radio.","Calca el círculo sobre el cuadrado de entretela de 16 × 16 cm y recórtalo.","Corta el círculo por la mitad: dos semicírculos, uno para cada esquina redonda."]},{title:"Cose las medias lunas",text:"Plancha un semicírculo sobre el revés de una pieza rosa, en el centro, con el lado recto a 1 cm del borde largo. Pon debajo una segunda pieza rosa, derecho con derecho, y cose por el borde curvo de la entretela.",details:["Coloca un semicírculo de entretela, con el lado del adhesivo hacia abajo, sobre el revés de una pieza rosa: en el centro, con el lado recto a 1 cm de un borde largo. Plánchalo.","Ponla sobre una segunda pieza rosa, derecho con derecho.","Cose a lo largo de la curva, justo por el borde de la entretela.","Haz la segunda igual."]},{title:"Recorta y da la vuelta",text:"Recorta la tela sobrante alrededor de la curva, haz piquetes en el margen y da la vuelta a cada media luna. Plancha.",details:["Recorta la tela que sobra alrededor de la curva y deja un margen estrecho.","Haz piquetes en el margen a lo largo de la curva para que quede plano.","Da la vuelta a las dos medias lunas por el lado recto y plánchalas. El lado recto queda abierto."]},{title:"Plancha la entretela",text:"Plancha la entretela de 21 × 29 cm sobre el revés del exterior, a 1 cm de cada borde. Dobla el exterior por la mitad y marca el centro con piquetes: es la base.",details:["Coloca el exterior con el revés hacia arriba.","Pon encima la entretela, con el adhesivo hacia abajo, a 1 cm de cada borde, y plánchala. El forro no lleva entretela.","Dobla el exterior por la mitad a lo ancho y haz un pequeño piquete en los dos extremos del doblez. El doblez es la base del neceser: ahí no hay costura."]},{title:"Cose las medias lunas al exterior",text:"Sobre el derecho del exterior pon una media luna en cada borde lateral, con el centro en la línea de la base y el borde recto al ras del lado, y cósela alrededor.",details:["Da la vuelta al exterior, con el derecho hacia arriba.","Pon una media luna en cada borde lateral: su borde recto abierto al ras del borde del exterior, su centro sobre los piquetes, en la línea de la base.","Cose cada una alrededor: por la curva, justo por el borde; por el lado recto, a 0,5 cm del borde. El lado recto quedará dentro de la costura lateral."]},{title:"Cremallera: primer lado",text:"El exterior con el derecho hacia arriba, la cremallera boca abajo en el centro de un lado corto y encima el forro boca abajo. Cose a 0,5 cm del borde.",details:["Coloca el exterior con el derecho hacia arriba.","Pon la cremallera boca abajo a lo largo de un lado de 23 cm, en el centro: sus extremos no llegan a los bordes laterales y quedan fuera de las costuras laterales.","Pon encima el forro boca abajo, borde con borde con el exterior.","Cose a través de todas las capas, a 0,5 cm del borde. Sin pespunte a lo largo de la cremallera."]},{title:"Cremallera: segundo lado",text:"Abre el forro hacia fuera de la cremallera. Dobla por la mitad el exterior y el forro, para que sus otros lados cortos lleguen al otro lado de la cremallera, y cóselos igual.",details:["Abre el forro hacia fuera de la cremallera.","Dobla el exterior por la mitad en la línea de la base, derecho con derecho, y el forro igual.","Sus otros lados cortos llegan ahora al otro lado de la cremallera: exterior, cremallera boca abajo, forro, como la primera vez.","Cose a 0,5 cm del borde. El exterior y el forro forman ahora un aro."]},{title:"Costuras laterales",text:"Abre la cremallera. Extiende el neceser, exterior con exterior y forro con forro, derecho con derecho, y cose los dos lados, dejando una abertura de 6 cm en el centro de un lado del forro.",details:["Primero abre la cremallera: por ella se da la vuelta al neceser.","Extiéndelo: el exterior derecho con derecho a un lado de la cremallera, el forro al otro.","Cose las dos costuras laterales a 0,5 cm del borde, también a través de las medias lunas.","En un lado del forro deja 6 cm abiertos, en el centro de la costura."]},{title:"Las esquinas de la base",text:"De cada esquina de abajo, dos del exterior y dos del forro, recorta un rectángulo de 3,5 × 2,5 cm: 3,5 cm a lo largo de la base, 2,5 cm a lo largo de la costura lateral. Abre cada esquina y cose de lado a lado.",details:["Marca en cada una de las cuatro esquinas de abajo un rectángulo de 3,5 × 2,5 cm: 3,5 cm a lo largo de la base, 2,5 cm a lo largo de la costura lateral.","Recórtalos.","Abre cada esquina y aplánala para que la costura lateral quede sobre el doblez de la base y los bordes cortados formen una línea recta.","Cose de lado a lado a 0,5 cm del borde. Haz las cuatro esquinas."]},{title:"Da la vuelta",text:"Da la vuelta al neceser por la abertura del forro y la cremallera abierta. Cierra la abertura a mano, mete el forro y cierra la cremallera.",details:["Saca el exterior por la abertura del forro y la cremallera abierta.","Dobla hacia dentro los bordes de la abertura y ciérrala a mano.","Mete el forro en el neceser, hasta las esquinas, y cierra la cremallera. Las medias lunas se han convertido en esquinas redondas rosas."]}],legend:[{title:"Exterior",text:"algodón estampado · 23 × 31 cm, doblado por la mitad: el doblez es la base"},{title:"Entretela",text:"fina, termoadhesiva · 21 × 29 cm, en el exterior, a 1 cm de los bordes"},{title:"Esquinas redondas ×2",text:"cuatro piezas rosas de 18 × 10 cm · semicírculos de entretela de 8 cm de radio, de un cuadrado de 16 × 16 cm"},{title:"Cremallera",text:"20 cm · en el centro de los lados cortos, sin pespunte"},{title:"Forro",text:"algodón · 23 × 31 cm, sin entretela"},{title:"Costuras",text:"todas de 0,5 cm · una abertura de 6 cm en el forro, cerrada a mano · esquinas: recortadas 3,5 × 2,5 cm"}]};export{r as default};
